{
  "format": "spec-v1",
  "product": {
    "name": "hn-digest",
    "version": "0.1.0",
    "kind": "agent"
  },
  "purpose": "Reads the current top stories on Hacker News and writes a short digest of the ones about a topic the caller names: each story's title, link, points and one plain sentence on why it matters. It serves a reader who wants to know what Hacker News is saying about one subject today without reading the whole front page.",
  "users": [
    {
      "who": "A caller who follows a subject",
      "wants": "A short digest of today's top Hacker News stories about that subject, with nothing in it that Hacker News did not say."
    }
  ],
  "source": {
    "kind": "account"
  },
  "features": [
    {
      "id": "F1",
      "name": "Topic Digest",
      "does": "Reads the current top stories on Hacker News and writes a short digest of the ones about the topic the caller names.",
      "inputs": [
        {
          "name": "topic",
          "kind": "text",
          "about": "The subject the digest is about, such as databases or Rust.",
          "required": true,
          "given_by": "person"
        }
      ],
      "outputs": [
        {
          "name": "digest",
          "kind": "text/markdown",
          "about": "A short digest. A header line with the topic and the time the stories were read, then `## Stories`, one entry per story: its title, its link, its points and one plain sentence on why it matters. When no story is about the topic, `## Stories` says so and lists none."
        }
      ],
      "requirements": [
        {
          "id": "F1.R1",
          "shall": "The agent shall read the current top stories from the Hacker News API, as many as the top stories to read setting says.",
          "kind": "behavior",
          "rationale": "The digest is drawn only from what Hacker News lists as its top stories now.",
          "priority": "must",
          "source": { "said": "Reads the current top stories on Hacker News ... how many top stories to read (default 30, 10 to 100)" },
          "verify": "test"
        },
        {
          "id": "F1.R2",
          "shall": "The agent shall put in the digest only the stories it read that are about the topic the caller names, at most as many as the stories in the digest setting says, in the order Hacker News ranks them.",
          "kind": "behavior",
          "rationale": "The caller wants the stories on their subject, and a short digest; keeping Hacker News's own order invents no ranking of its own.",
          "priority": "must",
          "source": { "said": "writes a short digest of the ones about a topic the caller names ... how many to put in the digest (default 5, 1 to 10)" },
          "verify": "test"
        },
        {
          "id": "F1.R3",
          "shall": "The agent shall give each story in the digest its title, link and points exactly as the Hacker News API gave them, and one plain sentence on why it matters written by the model.",
          "kind": "output",
          "rationale": "The facts of a story are Hacker News's; only the sentence is written.",
          "priority": "must",
          "source": { "said": "each story's title, link, points and one plain sentence on why it matters. ... It uses a model to write the sentences" },
          "verify": "test"
        },
        {
          "id": "F1.R4",
          "shall": "The agent shall refuse writing about stories it did not read from Hacker News, and shall leave out of the digest any story the model names that is not among the stories it read.",
          "kind": "refusal",
          "rationale": "A digest of Hacker News holds nothing from anywhere else.",
          "priority": "must",
          "source": { "said": "what it must refuse: Writing about stories it did not read from Hacker News" },
          "verify": "test"
        },
        {
          "id": "F1.R5",
          "shall": "The agent shall refuse inventing points, links or comments, and shall write a story's points and link only from the Hacker News API and no comments at all.",
          "kind": "refusal",
          "rationale": "Points and links a reader trusts must be the ones Hacker News shows.",
          "priority": "must",
          "source": { "said": "inventing points, links or comments" },
          "verify": "test"
        },
        {
          "id": "F1.R6",
          "shall": "The agent shall refuse posting, voting or commenting on Hacker News, and shall only read from it.",
          "kind": "refusal",
          "rationale": "It is a reader of Hacker News, never a participant.",
          "priority": "must",
          "source": { "said": "posting, voting or commenting on Hacker News. ... the public Hacker News API (read only, no key)" },
          "verify": "test"
        },
        {
          "id": "F1.R7",
          "shall": "When none of the stories it read is about the topic, the agent shall write a digest that says no top story is about the topic and lists no stories, and shall not call that a failure.",
          "kind": "behavior",
          "rationale": "Builder's recommendation, the person did not say: finding nothing on a subject is a true answer, not an error.",
          "priority": "must",
          "source": { "said": "writes a short digest of the ones about a topic the caller names" },
          "verify": "test"
        },
        {
          "id": "F1.R8",
          "shall": "When the caller names no topic, or a topic that is empty, the agent shall read nothing, write no digest and say that a topic is needed.",
          "kind": "input",
          "rationale": "Builder's recommendation, the person did not say: without a topic there is nothing to choose stories by.",
          "priority": "must",
          "source": { "said": "a topic the caller names" },
          "verify": "test"
        },
        {
          "id": "F1.R9",
          "shall": "When the Hacker News API cannot be reached or answers with something that is not a list of stories, the agent shall write no digest and shall say that Hacker News could not be read, rather than write from anything else.",
          "kind": "error",
          "rationale": "Builder's recommendation, the person did not say: a digest from partial or invented stories would break the refusals.",
          "priority": "must",
          "source": { "said": "It reaches one system, the public Hacker News API ... Writing about stories it did not read from Hacker News" },
          "verify": "test"
        },
        {
          "id": "F1.R10",
          "shall": "When a single story cannot be read from the Hacker News API, the agent shall leave that story out and go on with the others.",
          "kind": "error",
          "rationale": "Builder's recommendation, the person did not say: one missing item should not lose the whole digest, and nothing is invented for it.",
          "priority": "should",
          "source": { "said": "Reads the current top stories on Hacker News" },
          "verify": "test"
        },
        {
          "id": "F1.R11",
          "shall": "When the model fails or does not answer in the shape asked, the agent shall write no digest and shall say that the sentences could not be written.",
          "kind": "error",
          "rationale": "Builder's recommendation, the person did not say: a story without its sentence is not what was asked for, and a sentence is never made up without the model.",
          "priority": "must",
          "source": { "said": "It uses a model to write the sentences" },
          "verify": "test"
        }
      ],
      "acceptance": [
        {
          "id": "F1.A1",
          "gherkin": "Scenario: A digest of the top stories about a topic\n  Given the Hacker News API lists 30 top stories, 3 of them about databases\n  And top stories to read is 30 and stories in the digest is 5\n  When the caller asks for a digest about \"databases\"\n  Then the agent reads the 30 top stories\n  And the digest lists the 3 stories about databases in Hacker News's order\n  And each has its title, link and points as the API gave them and one plain sentence on why it matters",
          "checks": ["F1.R1", "F1.R2", "F1.R3"]
        },
        {
          "id": "F1.A2",
          "gherkin": "Scenario: The digest holds no more stories than the setting allows\n  Given 8 of the top stories are about databases\n  And stories in the digest is 5\n  When the caller asks for a digest about \"databases\"\n  Then the digest lists the first 5 of them in Hacker News's order",
          "checks": ["F1.R2"]
        },
        {
          "id": "F1.A3",
          "gherkin": "Scenario: A story the model names that was not read is left out\n  Given the model's answer names a story that is not among the stories read\n  When the agent writes the digest\n  Then that story is not in the digest",
          "checks": ["F1.R4"]
        },
        {
          "id": "F1.A4",
          "gherkin": "Scenario: Points and links come only from Hacker News\n  Given the model's answer gives a story other points and another link than the API gave\n  When the agent writes the digest\n  Then the digest shows the points and link the API gave\n  And the digest holds no comments",
          "checks": ["F1.R5"]
        },
        {
          "id": "F1.A5",
          "gherkin": "Scenario: The agent only reads from Hacker News\n  Given a run of the agent\n  When it reaches the Hacker News API\n  Then every request it makes is a read\n  And it never posts, votes or comments",
          "checks": ["F1.R6"]
        },
        {
          "id": "F1.A6",
          "gherkin": "Scenario: No top story is about the topic\n  Given none of the top stories is about \"basket weaving\"\n  When the caller asks for a digest about \"basket weaving\"\n  Then the digest says no top story is about the topic\n  And it lists no stories\n  And the run does not fail",
          "checks": ["F1.R7"]
        },
        {
          "id": "F1.A7",
          "gherkin": "Scenario: No topic is named\n  Given the caller names no topic\n  When the agent runs\n  Then it reads nothing from Hacker News\n  And it writes no digest\n  And it says a topic is needed",
          "checks": ["F1.R8"]
        },
        {
          "id": "F1.A8",
          "gherkin": "Scenario: Hacker News cannot be read\n  Given the Hacker News API does not answer\n  When the caller asks for a digest about \"databases\"\n  Then the agent writes no digest\n  And it says Hacker News could not be read",
          "checks": ["F1.R9"]
        },
        {
          "id": "F1.A9",
          "gherkin": "Scenario: One story cannot be read\n  Given one of the top stories cannot be read from the API\n  When the caller asks for a digest about \"databases\"\n  Then that story is left out\n  And the digest is written from the others",
          "checks": ["F1.R10"]
        },
        {
          "id": "F1.A10",
          "gherkin": "Scenario: The model fails\n  Given the model does not answer\n  When the caller asks for a digest about \"databases\"\n  Then the agent writes no digest\n  And it says the sentences could not be written",
          "checks": ["F1.R11"]
        }
      ]
    }
  ],
  "constraints": [
    {
      "id": "C1",
      "shall": "The agent shall spend no more than 1 USD per day on the model, and shall write no digest and say the day's ceiling is reached once it is.",
      "kind": "limit",
      "rationale": "The person set the ceiling; what happens when it is reached is the builder's recommendation.",
      "priority": "must",
      "source": { "said": "It uses a model to write the sentences, with a spending ceiling of 1 USD per day." },
      "verify": "test"
    },
    {
      "id": "C2",
      "shall": "The agent shall reach no system but the Hacker News API and the model, and shall send the Hacker News API no key.",
      "kind": "security",
      "priority": "must",
      "source": { "said": "It reaches one system, the public Hacker News API (read only, no key)." },
      "verify": "test"
    }
  ],
  "systems": [
    {
      "name": "Hacker News API",
      "reach": "read",
      "address": "https://hacker-news.firebaseio.com/v0",
      "why": "The public Hacker News API (the Firebase one): the top stories list and each story's title, link and points. Read only.",
      "credential": "none",
      "settings": []
    }
  ],
  "settings": [
    {
      "name": "top_stories_to_read",
      "kind": "integer",
      "default": 30,
      "min": 10,
      "max": 100,
      "set_by": "person",
      "about": "How many of the current top stories to read from Hacker News."
    },
    {
      "name": "stories_in_digest",
      "kind": "integer",
      "default": 5,
      "min": 1,
      "max": 10,
      "set_by": "person",
      "about": "How many stories, at most, to put in the digest."
    }
  ],
  "price": "Free",
  "open": []
}

changes.architecture.json:
{
  "title": "a topic digest of the Hacker News top stories",
  "environments": ["dev", "test", "production"],
  "systems": [
    {
      "name": "text-reasoning",
      "plain": "text reasoning",
      "capability": "text: one plain sentence on why a story matters, and judging whether a story's title is about a topic",
      "access": "trigger",
      "why": "Writing a plain sentence on why a story matters, and telling whether a story is about the caller's topic, are judgments.",
      "called_for": "It uses a model to write the sentences"
    }
  ],
  "kind": {
    "kind": "plugin-on-harness",
    "why": "A short program with one judgment: read the top stories, keep the ones on the topic, have each sentence written, put the digest together. A harness reading skills carries it."
  },
  "dependencies": [],
  "limits": {
    "cost": { "limit": "at most 1 USD per day", "why": "The statement says so: a spending ceiling of 1 USD per day." },
    "speed": { "limit": "a digest within 300 seconds", "why": "Reading at most 100 stories and one model call is one short pass." },
    "data": { "limit": "holds the stories only for the job; keeps nothing between runs; sends the model only the stories' titles and links", "why": "The stories are public, and nothing about the caller needs keeping." },
    "trust": { "limit": "takes jobs only from its owner; reads story titles as data, never as instructions; only reads from Hacker News", "why": "A story title is written by a stranger, and the agent must never post, vote or comment." }
  },
  "drivers": [
    {
      "key": "readable",
      "quality": "readability",
      "says": "A person reads the digest, so it is short and plain.",
      "from": "writes a short digest ... one plain sentence on why it matters"
    },
    {
      "key": "faithful",
      "quality": "faithfulness",
      "says": "Every title, link and point in the digest is the one Hacker News gave; nothing is invented.",
      "from": "Writing about stories it did not read from Hacker News; inventing points, links or comments"
    }
  ],
  "egress": [
    {
      "destination": "the public Hacker News API",
      "why": "The top stories list and each story's title, link and points come from it, read only and with no key.",
      "service": { "name": "hacker-news-api", "access": "read", "address": "https://hacker-news.firebaseio.com/v0" }
    }
  ],
  "formats": [
    {
      "piece": "topic",
      "direction": "in",
      "kind": "text",
      "convention": "A few words naming the subject, such as databases.",
      "given_by": "person",
      "why": "The caller names the subject in words."
    },
    {
      "piece": "digest",
      "direction": "out",
      "kind": "text/markdown",
      "convention": "A header with the topic and the time the stories were read, then `## Stories`, one entry per story with its title as a link, its points and one plain sentence on why it matters; when none is on the topic, `## Stories` says so and lists none.",
      "given_by": "agent",
      "why": "A person reads it."
    }
  ],
  "settings": [
    {
      "name": "top_stories_to_read",
      "kind": "preference",
      "label": "Top stories to read",
      "about": "How many of the current top stories to read from Hacker News.",
      "default": 30,
      "min": 10,
      "max": 100,
      "step": 1,
      "job_may_set": true,
      "why": "The person set it: default 30, 10 to 100."
    },
    {
      "name": "stories_in_digest",
      "kind": "preference",
      "label": "Stories in the digest",
      "about": "How many stories, at most, to put in the digest.",
      "default": 5,
      "min": 1,
      "max": 10,
      "step": 1,
      "job_may_set": true,
      "why": "The person set it: default 5, 1 to 10."
    }
  ],
  "skills": [
    {
      "name": "topic-digest",
      "responsibility": "Writes a short digest of the current Hacker News top stories about the topic the caller names.",
      "script": "Reads the top stories, keeps the ones on the topic, has the model write one sentence for each, and writes the digest as the reply."
    }
  ],
  "parts": [
    {
      "id": "hn-client",
      "name": "Hacker News client",
      "within": "topic-digest",
      "responsibility": "Reads the top story ids, then each story's item, a bounded number at a time, leaving out a story that cannot be read.",
      "reaches": "hacker-news-api"
    },
    {
      "id": "sentence-writer",
      "name": "sentence writer",
      "within": "topic-digest",
      "responsibility": "Asks the model, through the shared model caller, which of the stories read are about the topic and for one plain sentence on each.",
      "reaches": "text-reasoning"
    },
    {
      "id": "topic-filter",
      "name": "topic filter",
      "within": "topic-digest",
      "responsibility": "Keeps only the stories the model chose that are among those read, in Hacker News's order, up to stories_in_digest, taking each title, link and points from the item."
    },
    {
      "id": "digest-writer",
      "name": "digest writer",
      "within": "topic-digest",
      "responsibility": "Puts the Markdown digest together, or the empty digest when no story is on the topic."
    }
  ],
  "flow": [
    { "from": "caller", "to": "harness", "data": "the topic", "says": "The caller names the subject." },
    { "from": "harness", "to": "hn-client", "data": "the topic and the settings", "says": "The harness starts the script with the job and its settings." },
    { "from": "hacker-news-api", "to": "hn-client", "data": "the top story ids and each story's item", "says": "The client reads the top story ids, then each item." },
    { "from": "hn-client", "to": "sentence-writer", "data": "each story's id, title and link", "says": "The stories read go to the writer." },
    { "from": "sentence-writer", "to": "text-reasoning", "data": "the topic and the stories' ids and titles", "says": "The writer asks the model which stories are on the topic and for one sentence on each." },
    { "from": "sentence-writer", "to": "topic-filter", "data": "the chosen ids and their sentences", "says": "The model's choices are checked against the stories read." },
    { "from": "topic-filter", "to": "digest-writer", "data": "the kept stories with their sentences", "says": "The kept stories, with their facts from the items, are handed on." },
    { "from": "digest-writer", "to": "caller", "data": "the digest", "says": "The digest goes back as the reply, through the harness." }
  ],
  "decisions": [
    {
      "decided": "Code controls the job, and the model only chooses the stories on the topic and writes their sentences",
      "context": "Every run is the same: read the top stories, keep those on a topic, write one sentence each, put the digest together.",
      "drivers": ["cost", "speed", "faithful"],
      "why": "One model call per job bounds the spend, and code, not the model, takes every title, link and point from Hacker News, so nothing can be invented.",
      "alternatives": [
        { "option": "A model in control that reads Hacker News and writes the digest", "why_not": "What it spends and what it writes would not be bounded, and it could invent points and links." },
        { "option": "Matching the topic by keywords in code", "why_not": "A topic such as databases would miss a story titled with a product name; the judgment is the model's." }
      ],
      "consequences": [
        "The job's how is control script, intelligence called, contract full.",
        "The sentence writer answers by story id, and the filter drops any id that was not read."
      ]
    },
    {
      "decided": "A package on a harness, run once per job",
      "context": "A digest is asked for now and then, and needs nothing between jobs.",
      "drivers": ["cost", "data"],
      "why": "Nothing runs, and nothing is spent, between jobs.",
      "alternatives": [
        { "option": "A long-running service", "why_not": "It would cost while idle and hold state nobody needs." }
      ],
      "consequences": [
        "It opens no port and keeps no process between jobs."
      ]
    },
    {
      "decided": "Read the story items in parallel, a bounded number at a time",
      "context": "Up to 100 items are read, one request each.",
      "drivers": ["speed", "trust"],
      "why": "In parallel it stays well within 300 seconds, and the bound keeps it polite to a public service.",
      "alternatives": [
        { "option": "One at a time", "why_not": "100 requests in a row could be slow." },
        { "option": "All at once", "why_not": "100 requests at once is impolite to a free public service." }
      ],
      "consequences": [
        "The bound is a constant a test can see.",
        "A story whose item cannot be read is left out."
      ]
    },
    {
      "decided": "Answer with the digest in the reply, and store nothing",
      "context": "The caller wants the digest now.",
      "drivers": ["data", "speed", "readable"],
      "why": "The digest is short, and keeping it would hold data nobody asked to keep.",
      "alternatives": [
        { "option": "Store each digest and send a link", "why_not": "It needs a files system nobody asked for." }
      ],
      "consequences": [
        "The record names no files or database system."
      ]
    }
  ],
  "questions": []
}

changes.agent-descriptor.json:
{
  "format": "agent-descriptor-v1",
  "agent_version": "0.1.0",
  "does": "Reads the current top stories on Hacker News and writes a short digest of the ones about a topic you name: each story's title, link and points as Hacker News gives them, and one plain sentence on why it matters.",
  "offerings": [
    {
      "id": "topic-digest",
      "name": "Topic digest",
      "does": "Reads the current top stories on Hacker News and writes a short Markdown digest of the ones about the topic you name, with each story's title, link, points and one plain sentence on why it matters.",
      "inputs": [
        {
          "name": "topic",
          "kind": "text",
          "required": true,
          "given_by": "person",
          "about": "The subject the digest is about, such as databases or Rust."
        }
      ],
      "outputs": [
        {
          "name": "digest",
          "kind": "text/markdown",
          "when": "per_task",
          "about": "A short digest. A header line with the topic and the time the stories were read, then `## Stories`, one entry per story: its title, its link, its points and one plain sentence on why it matters. When no story is about the topic, `## Stories` says so and lists none."
        }
      ],
      "how": {
        "control": "script",
        "intelligence": "called",
        "cost": "metered",
        "contract": "full"
      }
    }
  ],
  "refusals": "Writing about stories it did not read from Hacker News, because a digest of Hacker News holds nothing from anywhere else; a story the model names that was not read is left out of the digest.\nInventing points, links or comments, because a reader trusts them as Hacker News's own; every title, link and point is taken from the Hacker News API, and the digest carries no comments.\nPosting, voting or commenting on Hacker News, because it is a reader and never a participant; it only reads from the API and says so when asked to do more.\nWriting a digest without a topic, because there is nothing to choose stories by; it reads nothing and says a topic is needed.\nFollowing instructions written in a story's title, because titles are written by strangers; they are read as data only and the digest is written as asked.",
  "records": [
    {
      "name": "the signed job manifest of each delivery",
      "when": "per_task"
    }
  ],
  "systems": [
    {
      "name": "hacker-news-api",
      "access": "read",
      "needs": "The public Hacker News API, read only and with no key: the current top story ids and each story's title, link and points. It reads from hacker-news.firebaseio.com."
    },
    {
      "name": "text-reasoning",
      "access": "trigger",
      "needs": "A text model, called once per job, to choose which of the stories read are about the topic and to write one plain sentence on why each matters."
    }
  ],
  "can_use": [
    {
      "schema": "https://schemas.agentmesh.ai/brand/v1",
      "reads": [
        "name",
        "legal.first_mention",
        "words.instead_of",
        "words.never_say"
      ],
      "required": false,
      "does": "writes the organization's name as the brand writes it, uses its first-mention form the first time, and keeps out the words the brand never says",
      "without": "writes the organization's name as the person gave it, and says that no brand profile was given"
    },
    {
      "schema": "https://schemas.agentmesh.ai/style-guide/v1",
      "reads": [
        "voice",
        "tone",
        "spelling",
        "words.prefer",
        "words.avoid"
      ],
      "required": false,
      "does": "writes in the organization's voice, tone and spelling, and uses the words it prefers in place of the ones it avoids",
      "without": "writes in a plain, neutral voice in the spelling of the words it was given, and says that no style guide was given"
    }
  ],
  "run_config": {
    "settings": [
      {
        "name": "top_stories_to_read",
        "kind": "preference",
        "default": 30,
        "label": "Top stories to read",
        "about": "How many of the current top stories to read from Hacker News.",
        "min": 10,
        "max": 100,
        "step": 1,
        "job_may_set": true
      },
      {
        "name": "stories_in_digest",
        "kind": "preference",
        "default": 5,
        "label": "Stories in digest",
        "about": "How many stories, at most, to put in the digest.",
        "min": 1,
        "max": 10,
        "step": 1,
        "job_may_set": true
      }
    ]
  }
}

