changes.test/delivered-formats.test.mjs:
// Every piece a job delivers is what its declared kind says it is.
// Written by the test writer into every suite it writes, the same bytes each
// time; it is the test writer's file and not the package's, so it is never
// edited here. The next suite the test writer writes for this package brings
// its current copy.
//   node --test test/delivered-formats.test.mjs
//
// What is worth pinning. An agent declares a kind for every output, and the
// next agent, the person reviewing it and the App all go by that kind, so a
// piece sent as one thing and declared as another breaks the hand-off. This
// holds each delivered piece to its kind, by its bytes:
//   - Markdown (text/markdown) parses as Markdown, not JSON or an HTML page,
//     and carries the convention its `about` sketches: the header's fields
//     and each fixed heading written in backticks, unless it is a case the
//     `about` gives a shape of its own ("When there was no sentence, the only
//     content is `## Nothing to count`"), and then it carries that case's;
//   - a JSON kind (application/vnd.<name>+json, or any +json) parses, and has
//     the top-level shape its `about` sketches in backticks, `{a, b}` or `[...]`;
//   - HTML is HTML, a URL is an address, an image, audio, video, PDF or
//     archive starts with its own signature, text is text;
//   - the media type pieces.json lists for a piece is the kind declared.
//
// How it is reached. The suite's other tests call checkDelivered(jobDir) on
// each job folder they fill, and assert it returns no problems. This file's
// own tests check the checker, check that every Markdown or JSON output's
// sketched convention is one a piece can be held to, and check each job folder
// under test/fixtures/delivered/ and under the folders DELIVERED names
// (separated by the path separator). Its tests run only when this file is run
// itself, so importing checkDelivered from it adds none.
//
// Nothing here touches a network, a model or a host.
import { test } from "node:test";
import assert from "node:assert/strict";
import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
import { delimiter, dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const trim = (s) => String(s ?? "").trim();
const base = (kind) => trim(kind).split(";")[0].trim().toLowerCase();

/** The package's declaration: its agent-descriptor.json beside test/, or a
 *  spec.json there, or null when neither is. */
export function readDeclaration(dir = join(HERE, "..")) {
  for (const f of ["agent-descriptor.json", "spec.json"]) {
    const at = join(dir, f);
    if (existsSync(at)) {
      try { return JSON.parse(readFileSync(at, "utf8")); } catch { return null; }
    }
  }
  return null;
}

/** Every declared output, by name: {kind, about}. Offerings and their steps
 *  (a descriptor) or jobs (a spec). */
export function declaredOutputs(decl) {
  const out = new Map();
  const add = (job) => {
    for (const o of Array.isArray(job?.outputs) ? job.outputs : []) {
      if (trim(o?.name) && trim(o?.kind) && !out.has(trim(o.name))) out.set(trim(o.name), { kind: trim(o.kind), about: trim(o.about) });
    }
  };
  for (const o of Array.isArray(decl?.offerings) ? decl.offerings : []) {
    add(o);
    for (const s of Array.isArray(o?.steps) ? o.steps : []) add(s);
  }
  for (const j of Array.isArray(decl?.jobs) ? decl.jobs : []) add(j);
  return out;
}

/** What a piece's `about` sketches: the fixed headings (`## ...` in
 *  backticks), the header's fields (`a, b` in backticks after "header" or
 *  "front matter"), and a JSON top-level shape (`{a, b?}` or `[...]`).
 *  A heading the `about` gives only to one case is not fixed: one in a
 *  sentence that opens on a case ("When there was no sentence, ... only
 *  `## Nothing to count`"), says it is only for one, or names the case
 *  straight after the heading (`## None` when nothing was found) is that
 *  case's, and each such sentence's headings are one of `cases`, a shape a
 *  piece may take instead (technical debt 647). */
export function conventionOf(about) {
  const text = String(about ?? "");
  const ticks = [...text.matchAll(/`([^`]+)`/g)].map((m) => m[1].trim());
  const isHeading = (t) => /^#{1,6} \S/.test(t);
  // Sentences, never ended inside backticks.
  const sentences = []; let cur = ""; let inTick = false;
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];
    cur += ch;
    if (ch === "`") inTick = !inTick;
    else if (!inTick && /[.!?]/.test(ch) && (i + 1 === text.length || /\s/.test(text[i + 1]))) { sentences.push(cur); cur = ""; }
  }
  if (cur.trim()) sentences.push(cur);
  const OPENS_ON_A_CASE = /^[\s"'(*_-]*(?:when|whenever|if|unless|otherwise|instead|without|where there (?:is|are|was|were) no|with no|for an? (?:empty|failed|refused|missing)|on (?:an? )?(?:empty|failure|refusal|error)|in (?:the|an?) (?:empty|failure|error|refusal) case)\b/i;
  const ONLY_FOR_ONE = /\bonly (?:when|if|for|in|on)\b|\binstead\b/i;
  const CASE_AFTER = /^`\s*(?:\([^)]*\)\s*)?(?:only\s+)?(?:when|if|unless|for an? (?:empty|failed|refused)|on (?:an? )?(?:empty|failure|refusal))\b/i;
  const fixed = []; const cases = [];
  for (const s of sentences) {
    const found = [...s.matchAll(/`([^`]+)`/g)].filter((m) => isHeading(m[1].trim()));
    if (!found.length) continue;
    if (OPENS_ON_A_CASE.test(s) || ONLY_FOR_ONE.test(s)) { cases.push(found.map((m) => m[1].trim())); continue; }
    const own = [];
    for (const m of found) {
      if (CASE_AFTER.test(s.slice(m.index + m[0].length - 1))) own.push(m[1].trim());
      else fixed.push(m[1].trim());
    }
    if (own.length) cases.push(own);
  }
  const headings = [...new Set(fixed)];
  const fm = /(?:header|front matter)[^`]{0,40}`([^`#]+)`/i.exec(String(about ?? ""));
  const header = fm ? fm[1].split(",").map((f) => f.trim().replace(/\?$/, "")).filter((f) => /^[A-Za-z_][\w .-]*$/.test(f)) : [];
  const sketch = ticks.find((t) => /^[{[]/.test(t)) ?? null;
  let shape = null;
  if (sketch?.startsWith("[")) shape = { type: "array" };
  else if (sketch?.startsWith("{")) {
    const inner = sketch.replace(/^\{/, "").replace(/\}$/, "");
    const keys = []; let depth = 0; let cur = "";
    for (const ch of inner) {
      if ("{[(".includes(ch)) depth += 1;
      if ("}])".includes(ch)) depth -= 1;
      if (ch === "," && depth === 0) { keys.push(cur); cur = ""; } else cur += ch;
    }
    keys.push(cur);
    const names = keys.map((k) => /^\s*([A-Za-z_$][\w$-]*)(\??)/.exec(k)).filter(Boolean);
    shape = { type: "object", keys: names.filter((m) => !m[2]).map((m) => m[1]) };
  }
  return { headings, cases, header, shape };
}

const SIGNATURES = {
  "image/png": (b) => b.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])),
  "image/jpeg": (b) => b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff,
  "image/gif": (b) => /^GIF8[79]a/.test(b.subarray(0, 6).toString("latin1")),
  "image/webp": (b) => b.subarray(0, 4).toString("latin1") === "RIFF" && b.subarray(8, 12).toString("latin1") === "WEBP",
  "application/pdf": (b) => b.subarray(0, 5).toString("latin1") === "%PDF-",
  "audio/wav": (b) => b.subarray(0, 4).toString("latin1") === "RIFF" && b.subarray(8, 12).toString("latin1") === "WAVE",
  "audio/mpeg": (b) => b.subarray(0, 3).toString("latin1") === "ID3" || (b[0] === 0xff && (b[1] & 0xe0) === 0xe0),
  "video/mp4": (b) => b.subarray(4, 8).toString("latin1") === "ftyp",
  "application/gzip": (b) => b[0] === 0x1f && b[1] === 0x8b,
  "application/zip": (b) => b.subarray(0, 4).toString("latin1") === "PK\u0003\u0004",
  "application/x-tar": (b) => b.subarray(257, 262).toString("latin1") === "ustar",
};
SIGNATURES["audio/x-wav"] = SIGNATURES["audio/wave"] = SIGNATURES["audio/wav"];
SIGNATURES["application/x-gzip"] = SIGNATURES["application/gzip"];

/** The bytes as UTF-8 text, or null when they are not text. */
export function textOf(bytes) {
  const b = Buffer.isBuffer(bytes) ? bytes : Buffer.from(String(bytes ?? ""), "utf8");
  if (b.includes(0)) return null;
  try { return new TextDecoder("utf-8", { fatal: true }).decode(b); } catch { return null; }
}

const parsesAsJson = (text) => { try { JSON.parse(text); return true; } catch { return false; } };
const escape = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
/** A heading line as a pattern: `## <title>` stands for any title. */
const headingPattern = (h) => new RegExp(`^${escape(h).replace(/<[^>]*>/g, ".+")}\\s*$`, "im");

/** Every way these bytes are not what `kind` (with its `about`) says, as
 *  sentences; empty when they are. */
export function formatProblems(bytes, kind, about = "", what = "the piece") {
  const k = base(kind);
  const b = Buffer.isBuffer(bytes) ? bytes : Buffer.from(String(bytes ?? ""), "utf8");
  const out = [];
  if (!b.length) return [`${what} is empty`];
  const text = textOf(b);
  const conv = conventionOf(about);
  if (k === "text/markdown") {
    if (text === null) return [`${what} is declared text/markdown and is not text`];
    const t = text.trim();
    if (/^[{[]/.test(t) && parsesAsJson(t)) return [`${what} is declared text/markdown and is JSON`];
    if (/^<(!doctype html|html)\b/i.test(t)) return [`${what} is declared text/markdown and is an HTML page`];
    // A piece carrying every heading of a case the about gives its own shape
    // is that case, and is held to nothing more (technical debt 647).
    if ((conv.cases ?? []).some((c) => c.length && c.every((h) => headingPattern(h).test(text)))) return out;
    for (const h of conv.headings) if (!headingPattern(h).test(text)) out.push(`${what} is missing the heading ${h} its convention names`);
    if (conv.header.length) {
      // The header is front matter, or the lines before the first heading of
      // the second level, so a title line (# Title) may come first. A field
      // may be bold or a list item: "source: x", "**Source:** x", "- source: x".
      const fm = /^---\r?\n([\s\S]*?)\r?\n---/.exec(t);
      const top = fm ? fm[1] : t.split(/^#{2,6} /m)[0];
      for (const f of conv.header) {
        if (!new RegExp(`^\\s*(?:[-*]\\s+)?(?:\\*\\*|__)?${escape(f)}(?:\\*\\*|__)?\\s*:`, "im").test(top)
          && !new RegExp(`^\\s*(?:[-*]\\s+)?(?:\\*\\*|__)${escape(f)}\\s*:(?:\\*\\*|__)`, "im").test(top)) {
          out.push(`${what} has no ${f}: line in its header`);
        }
      }
    }
    return out;
  }
  if (k === "application/json" || k.endsWith("+json")) {
    if (text === null) return [`${what} is declared ${k} and is not text`];
    let doc;
    try { doc = JSON.parse(text); } catch (e) { return [`${what} is declared ${k} and does not parse as JSON: ${e.message}`]; }
    if (conv.shape?.type === "array" && !Array.isArray(doc)) out.push(`${what} is declared as a JSON list and is not one`);
    if (conv.shape?.type === "object") {
      if (!doc || typeof doc !== "object" || Array.isArray(doc)) out.push(`${what} is declared as a JSON object and is not one`);
      else for (const key of conv.shape.keys) if (!(key in doc)) out.push(`${what} has no top-level ${key} its shape names`);
    }
    return out;
  }
  if (k === "text/html") {
    if (text === null) return [`${what} is declared text/html and is not text`];
    if (/^[{[]/.test(text.trim()) && parsesAsJson(text.trim())) return [`${what} is declared text/html and is JSON`];
    if (!/<(html|head|body|main|section|article|div|p|h[1-6]|table|ul|ol)\b/i.test(text)) out.push(`${what} is declared text/html and carries no HTML element`);
    return out;
  }
  if (k === "image/svg+xml" || k === "application/xml" || k === "text/xml" || k.endsWith("+xml")) {
    if (text === null || !text.trim().startsWith("<")) return [`${what} is declared ${k} and is not XML`];
    if (k === "image/svg+xml" && !/<svg\b/i.test(text)) out.push(`${what} is declared image/svg+xml and carries no svg element`);
    return out;
  }
  if (SIGNATURES[k]) return SIGNATURES[k](b) ? [] : [`${what} is declared ${k} and does not start the way a ${k} file does`];
  if (k === "text/vtt") return text !== null && text.startsWith("WEBVTT") ? [] : [`${what} is declared text/vtt and does not start WEBVTT`];
  if (k === "application/x-subrip") return text !== null && text.includes("-->") ? [] : [`${what} is declared application/x-subrip and carries no cue`];
  if (k === "url" || k === "text/uri-list") {
    const lines = (text ?? "").split(/\r?\n/).map((l) => l.trim()).filter((l) => l && !l.startsWith("#"));
    if (text === null || !lines.length || !lines.every((l) => /^[a-z][a-z0-9+.-]*:\/\/\S+$/i.test(l))) return [`${what} is declared ${k} and is not one address per line`];
    return [];
  }
  if (k === "identifier") {
    if (text === null || /\r?\n./.test(text.trim()) || text.trim().length > 512) return [`${what} is declared identifier and is not one short line`];
    return [];
  }
  if (k === "text" || k.startsWith("text/")) return text === null ? [`${what} is declared ${k} and is not text`] : [];
  return [];
}

/** The pieces a job folder delivered: pieces.json, as {name, path, media_type}. */
export function piecesIn(jobDir) {
  const at = join(jobDir, "pieces.json");
  if (!existsSync(at)) return [];
  const doc = JSON.parse(readFileSync(at, "utf8"));
  const list = Array.isArray(doc) ? doc : Array.isArray(doc?.pieces) ? doc.pieces : [];
  return list.filter((e) => e && typeof e === "object" && trim(e.name));
}

/** The declared output a piece is filed under: its own name, or "<output>
 *  (<file>)" for one of several files under one output. */
export function outputFor(name, outputs) {
  const n = trim(name).toLowerCase();
  for (const [d, o] of outputs) {
    const dl = d.toLowerCase();
    if (n === dl || n.startsWith(`${dl} (`)) return { name: d, ...o };
  }
  return null;
}

/** Every delivered piece in a job folder that is not what its declared kind
 *  says, as sentences. A piece no output declares is said only with
 *  { undeclared: true }, because the package maker already warns on it and
 *  an agent released before the format rules may carry one. */
export function checkDelivered(jobDir, { declaration = readDeclaration(), undeclared = false } = {}) {
  const outputs = declaredOutputs(declaration);
  const problems = [];
  for (const p of piecesIn(jobDir)) {
    const o = outputFor(p.name, outputs);
    if (!o) {
      if (undeclared) problems.push(`the piece ${JSON.stringify(p.name)} is delivered and no output declares it`);
      continue;
    }
    const what = `the piece ${JSON.stringify(p.name)}`;
    if (trim(p.media_type) && o.kind.includes("/") && base(p.media_type) !== base(o.kind)) {
      problems.push(`${what} is listed as ${base(p.media_type)} and declared ${base(o.kind)}`);
    }
    if (!trim(p.path)) continue;
    const at = join(jobDir, p.path);
    if (!existsSync(at) || !statSync(at).isFile()) { problems.push(`${what} is listed at ${p.path} and is not there`); continue; }
    problems.push(...formatProblems(readFileSync(at), o.kind, o.about, what));
  }
  return problems;
}

/** A piece made from a convention, the smallest one that keeps it: the
 *  header's fields, then each heading with a line under it; or the JSON
 *  shape's keys. Null for a kind with nothing sketched to make. */
export function sampleOf(kind, about) {
  const k = base(kind); const c = conventionOf(about);
  if (k === "text/markdown") {
    // A Markdown piece whose about sketches no convention has nothing to make
    // a sample from; it is held only to being Markdown and not JSON or a page.
    if (!c.headings.length && !c.header.length) return null;
    const head = c.header.length ? `---\n${c.header.map((f) => `${f}: x`).join("\n")}\n---\n\n` : "";
    return head + c.headings.map((h) => `${h.replace(/<[^>]*>/g, "Example")}\n\nA line.\n`).join("\n");
  }
  if ((k === "application/json" || k.endsWith("+json")) && c.shape) {
    return JSON.stringify(c.shape.type === "array" ? [] : Object.fromEntries(c.shape.keys.map((key) => [key, null])));
  }
  return null;
}

/** The job folders this file checks by itself. */
export function jobFoldersToCheck(env = process.env, here = HERE) {
  const roots = [join(here, "fixtures", "delivered"), ...trim(env.DELIVERED).split(delimiter).filter(Boolean)];
  const out = [];
  for (const r of roots) {
    if (!existsSync(r) || !statSync(r).isDirectory()) continue;
    if (existsSync(join(r, "pieces.json"))) out.push(r);
    for (const n of readdirSync(r)) if (existsSync(join(r, n, "pieces.json"))) out.push(join(r, n));
  }
  return out;
}

const ranDirectly = Boolean(process.argv[1]) && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (ranDirectly) {
  test("markdown is held to its convention, and JSON or a page is not markdown", () => {
    const about = "Markdown: a header `source, read_at`, then `## Key points`, then `## <page title>` per page.";
    const good = "---\nsource: https://example.com\nread_at: 2026-10-27\n---\n\n## Key points\n\n- one\n\n## Example page\n\ntext\n";
    assert.deepEqual(formatProblems(good, "text/markdown", about), []);
    assert.match(formatProblems('{"points":[]}', "text/markdown", about).join(" "), /is JSON/);
    assert.match(formatProblems("## Points\n", "text/markdown", about).join(" "), /missing the heading ## Key points/);
    assert.match(formatProblems("## Key points\n## A page\n", "text/markdown", about).join(" "), /no source: line/);
  });

  test("a json kind parses and has the top-level shape its about sketches", () => {
    const about = "the cues, `{cues, font?, at}`";
    assert.deepEqual(formatProblems('{"cues":[],"at":1}', "application/vnd.example.cues+json", about), []);
    assert.match(formatProblems('{"cues":[]}', "application/vnd.example.cues+json", about).join(" "), /no top-level at/);
    assert.match(formatProblems("cues: none", "application/vnd.example.cues+json", about).join(" "), /does not parse as JSON/);
    assert.match(formatProblems("{}", "application/vnd.example.list+json", "`[ids]`").join(" "), /JSON list/);
  });

  test("html, addresses, identifiers, text and signed binaries are each what they say", () => {
    assert.deepEqual(formatProblems("<!doctype html><html><body><p>x</p></body></html>", "text/html"), []);
    assert.match(formatProblems('{"a":1}', "text/html").join(" "), /is JSON/);
    assert.deepEqual(formatProblems("https://example.com/a\nhttps://example.com/b\n", "url"), []);
    assert.match(formatProblems("see the page", "url").join(" "), /one address per line/);
    assert.match(formatProblems("a\nb", "identifier").join(" "), /one short line/);
    assert.deepEqual(formatProblems(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0]), "image/png"), []);
    assert.match(formatProblems("not a picture", "image/png").join(" "), /does not start the way/);
    assert.match(formatProblems(Buffer.from([0xff, 0xfe, 0x00]), "text/plain").join(" "), /is not text/);
    assert.match(formatProblems("", "text/plain").join(" "), /is empty/);
  });

  test("every declared markdown or json output sketches a convention a piece can be held to", () => {
    const outputs = declaredOutputs(readDeclaration());
    for (const [name, o] of outputs) {
      const sample = sampleOf(o.kind, o.about);
      if (sample === null) continue;
      assert.deepEqual(formatProblems(sample, o.kind, o.about, name), [], `${name}: a piece made from its own convention fails it`);
      if (base(o.kind) === "text/markdown" && conventionOf(o.about).headings.length) {
        assert.ok(formatProblems(JSON.stringify({ [name]: sample }), o.kind, o.about, name).length, `${name}: a JSON dump would pass as its markdown`);
      }
    }
  });

  test("every job folder kept as a delivered example holds pieces in their declared formats", (t) => {
    const folders = jobFoldersToCheck();
    if (!folders.length) { t.skip("no delivered examples under test/fixtures/delivered and none named by DELIVERED"); return; }
    for (const d of folders) assert.deepEqual(checkDelivered(d), [], d);
  });
}

changes.test/f1-topic-digest.test.mjs:
// The topic digest decides which Hacker News stories a reader sees about a
// subject, and every fact it shows them must be Hacker News's own.
//
// What is worth pinning: it reads as many top stories as the setting says and
// no more; it keeps only the stories the model chose that it actually read, in
// Hacker News's order, no more than the setting allows; every title, link and
// point comes from the API and never from the model, and no comment is
// written; it only ever reads (GET) from Hacker News, and sends it no key;
// with no story on the topic it still writes the digest, saying so; with no
// topic it reads nothing; when Hacker News cannot be read, or the model fails,
// or the day's spending ceiling is reached, it writes no digest and says why;
// and one story that cannot be read is left out without losing the others.
// The model is reached only through its four settings.
// Nothing here touches a network or a model: Hacker News and the model are
// functions the test hands in, at an address the test makes up.
// Run: node --test test/f1-topic-digest.test.mjs
import { test } from "node:test";
import assert from "node:assert/strict";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import {
  CEILING_REACHED, CeilingReached, HN_UNREADABLE, MODEL_FAILED, NO_TOPIC, NONE_ON_TOPIC,
  callModel, keepPicked, readTopStories, runDigest, settingsOf, topicOf,
} from "../scripts/topic-digest.mjs";
import { checkDelivered } from "./delivered-formats.test.mjs";
import { worked } from "./worked-values.test.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const ADDRESS = "https://hn.test/v0";
const ENV = { HACKER_NEWS_API_ADDRESS: ADDRESS };
const NOW = () => new Date("2026-11-11T09:30:00Z");

// A folder that goes away afterwards, whatever the test did in it.
async function inJob(body) {
  const at = mkdtempSync(join(tmpdir(), "hn-digest-"));
  const job = join(at, "job-1");
  mkdirSync(join(job, "out"), { recursive: true });
  try { await body(job); } finally { rmSync(at, { recursive: true, force: true }); }
}

// Stories 1..n; those in `on` are about databases.
function storiesOf(n, on = []) {
  return Array.from({ length: n }, (_, k) => {
    const id = k + 1;
    return on.includes(id)
      ? { id, title: `Postgres trick number ${id}`, url: `https://example.com/db/${id}`, score: 100 + id }
      : { id, title: `Gardening note ${id}`, url: `https://example.com/garden/${id}`, score: 10 + id };
  });
}

// Hacker News as a function: the top stories list, then each item.
function hn(stories, { ids = stories.map((s) => s.id), fail = new Set(), down = false, list } = {}) {
  const calls = [];
  const byId = new Map(stories.map((s) => [s.id, s]));
  const json = (v) => ({ ok: true, status: 200, json: async () => v, text: async () => JSON.stringify(v) });
  const fetchImpl = async (url, init = {}) => {
    calls.push({ url: String(url), init });
    if (down) throw new Error("connect ECONNREFUSED");
    const u = String(url);
    if (u === `${ADDRESS}/topstories.json`) return json(list === undefined ? ids : list);
    const m = /\/item\/(\d+)\.json$/.exec(u);
    if (m) {
      const id = Number(m[1]);
      if (fail.has(id)) return { ok: false, status: 500, json: async () => null, text: async () => "" };
      const s = byId.get(id);
      return json(s ? { id, type: "story", by: "someone", title: s.title, url: s.url, score: s.score, descendants: 7, kids: [9001, 9002] } : null);
    }
    return { ok: false, status: 404, json: async () => null, text: async () => "" };
  };
  return { fetchImpl, calls, items: () => calls.filter((c) => /\/item\//.test(c.url)) };
}

// The model as a function: it picks the ids given, with a sentence each.
function picker(ids, extra = {}) {
  const prompts = [];
  const call = async (prompt) => {
    prompts.push(String(prompt));
    return JSON.stringify({ picks: ids.map((id) => ({ id, why: `It matters because of story ${id}.`, ...extra })) });
  };
  return { call, prompts };
}

const storyLine = (s) => new RegExp(`^- \\[${s.title.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\]\\(${s.url.replace(/[.*+?^${}()|[\]\\/]/g, "\\$&")}\\), ${s.score} points?\\. It matters because of story ${s.id}\\.$`, "m");
const listed = (digest) => digest.split("\n").filter((l) => /^- \[/.test(l)).length;

// ── the good case ───────────────────────────────────────────────────────────

const A1_STORIES = storiesOf(50, [4, 11, 20]);
const A1_ON_TOPIC = worked([4, 11, 20], () => A1_STORIES.filter((s) => s.title.startsWith("Postgres")).map((s) => s.id), "the stories about databases in A1, in Hacker News's order");
const A1_READ = worked(30, () => Math.min(A1_STORIES.length, 30), "the stories read in A1, the default top_stories_to_read");

test("[F1.A1] a digest lists the stories about the topic in Hacker News's order, each with its title, link, points and one sentence", async () => {
  await inJob(async (job) => {
    const site = hn(A1_STORIES);
    const model = picker([20, 4, 11]);
    const out = await runDigest({ text: "databases", context: { settings: { top_stories_to_read: 30, stories_in_digest: 5 } }, env: ENV, fetchImpl: site.fetchImpl, call: model.call, now: NOW, jobDir: job });
    assert.equal(out.code, 0, out.reply);
    assert.equal(site.items().length, A1_READ, "it read the 30 top stories and no more");
    assert.equal(model.prompts.length, 1, "one model call for the job");
    const digest = out.digest;
    assert.match(digest, /^## Stories$/m);
    assert.match(digest, /^topic: databases$/m);
    assert.match(digest, /^read_at: 2026-11-11T09:30:00\.000Z$/m);
    const kept = A1_ON_TOPIC.map((id) => A1_STORIES.find((s) => s.id === id));
    for (const s of kept) assert.match(digest, storyLine(s));
    const order = kept.map((s) => digest.indexOf(`[${s.title}]`));
    assert.deepEqual(order, [...order].sort((a, b) => a - b), "in Hacker News's order, not the model's");
    assert.equal(listed(digest), A1_ON_TOPIC.length);
    assert.equal(out.reply, digest, "the digest is the reply");
    assert.equal(readFileSync(join(job, "out", "digest.md"), "utf8"), digest);
    assert.deepEqual(checkDelivered(job), []);
  });
});

test("[F1.R1] it reads as many top stories as the setting says, and the settings keep their defaults and ranges", async () => {
  const site = hn(storiesOf(50, [3]));
  const out = await runDigest({ text: "databases", context: { settings: { top_stories_to_read: 10 } }, env: ENV, fetchImpl: site.fetchImpl, call: picker([3]).call, now: NOW });
  assert.equal(out.code, 0, out.reply);
  assert.equal(site.items().length, 10);
  assert.deepEqual(settingsOf({}), { top_stories_to_read: 30, stories_in_digest: 5 });
  assert.deepEqual(settingsOf({ settings: { top_stories_to_read: 500, stories_in_digest: 0 } }), { top_stories_to_read: 100, stories_in_digest: 1 });
  assert.deepEqual(settingsOf({ settings: { top_stories_to_read: 3, stories_in_digest: 99 } }), { top_stories_to_read: 10, stories_in_digest: 10 });
  assert.deepEqual(settingsOf({ settings: { top_stories_to_read: "lots" } }), { top_stories_to_read: 30, stories_in_digest: 5 });
});

const A2_STORIES = storiesOf(30, [2, 5, 7, 9, 13, 17, 22, 28]);
const A2_KEPT = worked([2, 5, 7, 9, 13], () => A2_STORIES.filter((s) => s.title.startsWith("Postgres")).map((s) => s.id).slice(0, 5), "the first 5 of the 8 stories about databases in A2");

test("[F1.A2] the digest holds no more stories than the setting allows, the first in Hacker News's order", async () => {
  const site = hn(A2_STORIES);
  const model = picker([28, 22, 17, 13, 9, 7, 5, 2]);
  const out = await runDigest({ text: "databases", context: { settings: { stories_in_digest: 5 } }, env: ENV, fetchImpl: site.fetchImpl, call: model.call, now: NOW });
  assert.equal(out.code, 0, out.reply);
  assert.equal(listed(out.digest), A2_KEPT.length);
  for (const id of A2_KEPT) assert.match(out.digest, storyLine(A2_STORIES.find((s) => s.id === id)));
  assert.equal(out.digest.includes("Postgres trick number 17"), false);
});

// ── the refusals ────────────────────────────────────────────────────────────

test("[F1.A3] a story the model names that was not among the stories read is left out", async () => {
  const site = hn(storiesOf(30, [6]));
  const call = async () => JSON.stringify({ picks: [{ id: 6, why: "It matters because of story 6." }, { id: 999, title: "A story nobody read", url: "https://elsewhere.test/999", why: "Invented." }] });
  const out = await runDigest({ text: "databases", context: {}, env: ENV, fetchImpl: site.fetchImpl, call, now: NOW });
  assert.equal(out.code, 0, out.reply);
  assert.equal(listed(out.digest), 1);
  assert.equal(out.digest.includes("A story nobody read"), false);
  assert.equal(out.digest.includes("elsewhere.test"), false);
  const read = storiesOf(3).map((s) => ({ id: s.id, title: s.title, url: s.url, points: s.score }));
  assert.deepEqual(keepPicked(read, [{ id: 42, why: "x" }, { id: 2, why: "y" }], 5).map((s) => s.id), [2]);
});

test("[F1.A4] points and links come only from Hacker News, and the digest holds no comments", async () => {
  const stories = storiesOf(30, [8]);
  const site = hn(stories);
  const call = async () => JSON.stringify({ picks: [{ id: 8, why: "It matters because of story 8.", points: 5000, score: 5000, url: "https://fake.test/8", link: "https://fake.test/8", comments: ["A comment the model made up."] }] });
  const out = await runDigest({ text: "databases", context: {}, env: ENV, fetchImpl: site.fetchImpl, call, now: NOW });
  assert.equal(out.code, 0, out.reply);
  assert.match(out.digest, storyLine(stories.find((s) => s.id === 8)));
  assert.equal(out.digest.includes("5000"), false, "the model's points are not shown");
  assert.equal(out.digest.includes("fake.test"), false, "the model's link is not shown");
  assert.equal(out.digest.includes("A comment the model made up"), false);
  assert.equal(/comment/i.test(out.digest), false, "no comments at all");
});

test("[F1.A5] every request it makes of Hacker News is a read, and it never posts, votes or comments", async () => {
  const stories = storiesOf(30, [1, 2]);
  const site = hn(stories);
  const modelCalls = [];
  const env = { ...ENV, MODEL_NAME: "a-model", MODEL_ENDPOINT: "https://model.test", MODEL_KEY: "", MODEL_PROTOCOL: "anthropic-messages" };
  const fetchImpl = async (url, init = {}) => {
    if (String(url).startsWith("https://model.test")) {
      modelCalls.push({ url: String(url), init });
      const text = JSON.stringify({ picks: [{ id: 1, why: "It matters because of story 1." }] });
      return { ok: true, status: 200, json: async () => ({ content: [{ type: "text", text }] }), text: async () => JSON.stringify({ content: [{ type: "text", text }] }) };
    }
    return site.fetchImpl(url, init);
  };
  const out = await runDigest({ text: "databases", context: {}, env, fetchImpl, now: NOW });
  assert.equal(out.code, 0, out.reply);
  assert.equal(modelCalls.length, 1);
  assert.ok(site.calls.length > 0);
  for (const c of site.calls) {
    assert.ok(c.url.startsWith(ADDRESS), c.url);
    assert.equal(String(c.init?.method ?? "GET").toUpperCase(), "GET", `${c.url} is a read`);
    assert.equal(c.init?.body, undefined, "a read sends nothing");
  }
});

// ── the empty case ──────────────────────────────────────────────────────────

test("[F1.A6] with no top story about the topic, the digest says so, lists none, and the run does not fail", async () => {
  await inJob(async (job) => {
    const site = hn(storiesOf(30));
    const out = await runDigest({ text: "basket weaving", context: {}, env: ENV, fetchImpl: site.fetchImpl, call: picker([]).call, now: NOW, jobDir: job });
    assert.equal(out.code, 0, out.reply);
    assert.match(out.digest, /^## Stories$/m);
    assert.ok(out.digest.includes(NONE_ON_TOPIC("basket weaving")));
    assert.match(NONE_ON_TOPIC("basket weaving"), /No top story is about basket weaving/);
    assert.equal(listed(out.digest), 0);
    assert.deepEqual(checkDelivered(job), []);
  });
});

test("[F1.A7] with no topic it reads nothing, writes no digest and says a topic is needed", async () => {
  for (const text of ["", "   \n  ", undefined]) {
    await inJob(async (job) => {
      const site = hn(storiesOf(30));
      const model = picker([1]);
      const out = await runDigest({ text, context: {}, env: ENV, fetchImpl: site.fetchImpl, call: model.call, now: NOW, jobDir: job });
      assert.equal(out.code, 3);
      assert.equal(out.reply, NO_TOPIC);
      assert.match(NO_TOPIC, /a topic is needed/i);
      assert.equal(out.digest, null);
      assert.equal(site.calls.length, 0, "nothing was read from Hacker News");
      assert.equal(model.prompts.length, 0, "the model was not called");
      assert.equal(existsSync(join(job, "pieces.json")), false, "no digest was filed");
    });
  }
  assert.equal(topicOf("  databases \n"), "databases");
  assert.equal(topicOf(""), "");
});

// ── the failure cases ───────────────────────────────────────────────────────

test("[F1.A8] when Hacker News does not answer, or answers with no list, it writes no digest and says Hacker News could not be read", async () => {
  for (const site of [hn(storiesOf(30), { down: true }), hn(storiesOf(30), { list: { error: "nope" } })]) {
    await inJob(async (job) => {
      const model = picker([1]);
      const out = await runDigest({ text: "databases", context: {}, env: ENV, fetchImpl: site.fetchImpl, call: model.call, now: NOW, jobDir: job });
      assert.equal(out.code, 1);
      assert.ok(out.reply.startsWith(HN_UNREADABLE), out.reply);
      assert.match(HN_UNREADABLE, /Hacker News could not be read/);
      assert.equal(out.digest, null);
      assert.equal(model.prompts.length, 0);
      assert.equal(existsSync(join(job, "pieces.json")), false);
    });
  }
  const noAddress = await runDigest({ text: "databases", context: {}, env: {}, fetchImpl: hn(storiesOf(3)).fetchImpl, call: picker([1]).call, now: NOW });
  assert.equal(noAddress.code, 1);
  assert.match(noAddress.reply, /HACKER_NEWS_API_ADDRESS/);
  await assert.rejects(readTopStories({ address: ADDRESS, count: 30, fetchImpl: hn([], { down: true }).fetchImpl }), /Hacker News could not be read/);
});

test("[F1.A9] a story that cannot be read is left out, and the digest is written from the others", async () => {
  const stories = storiesOf(30, [4, 5]);
  const site = hn(stories, { fail: new Set([5]) });
  const model = picker([4, 5]);
  const out = await runDigest({ text: "databases", context: {}, env: ENV, fetchImpl: site.fetchImpl, call: model.call, now: NOW });
  assert.equal(out.code, 0, out.reply);
  assert.match(out.digest, storyLine(stories.find((s) => s.id === 4)));
  assert.equal(out.digest.includes("Postgres trick number 5"), false);
  assert.equal(model.prompts[0].includes("Postgres trick number 5"), false, "the model was never shown it");
  const read = await readTopStories({ address: ADDRESS, count: 30, fetchImpl: hn(stories, { fail: new Set([5]) }).fetchImpl });
  assert.deepEqual(read.stories.map((s) => s.id).includes(5), false);
  assert.deepEqual(read.skipped, [5]);
});

test("[F1.A10] when the model fails or answers in another shape, it writes no digest and says the sentences could not be written", async () => {
  const failing = [
    async () => { throw new Error("socket hang up"); },
    async () => "Here are some stories I like.",
    async () => JSON.stringify({ stories: [] }),
    async () => JSON.stringify({ picks: [{ id: 4 }] }),
  ];
  for (const call of failing) {
    await inJob(async (job) => {
      const out = await runDigest({ text: "databases", context: {}, env: ENV, fetchImpl: hn(storiesOf(30, [4])).fetchImpl, call, now: NOW, jobDir: job });
      assert.equal(out.code, 1);
      assert.ok(out.reply.startsWith(MODEL_FAILED), out.reply);
      assert.match(MODEL_FAILED, /the sentences could not be written/);
      assert.equal(out.digest, null);
      assert.equal(existsSync(join(job, "pieces.json")), false);
    });
  }
});

test("[F1.R11] the model is reached only through its four settings, and a missing one is named", async () => {
  await assert.rejects(callModel("hello", { env: { MODEL_ENDPOINT: "https://model.test", MODEL_PROTOCOL: "openai-chat" }, fetchImpl: async () => { throw new Error("must not be called"); } }), /MODEL_NAME/);
  await assert.rejects(callModel("hello", { env: { MODEL_NAME: "m", MODEL_PROTOCOL: "openai-chat" }, fetchImpl: async () => { throw new Error("must not be called"); } }), /MODEL_ENDPOINT/);
  await assert.rejects(callModel("hello", { env: { MODEL_NAME: "m", MODEL_ENDPOINT: "https://model.test" }, fetchImpl: async () => { throw new Error("must not be called"); } }), /MODEL_PROTOCOL/);
  const shapes = {
    "anthropic-messages": { url: "https://model.test/v1/messages", answer: { content: [{ type: "text", text: "A" }] }, key: ["x-api-key", "k"] },
    "openai-chat": { url: "https://model.test/chat/completions", answer: { choices: [{ message: { content: "A" } }] }, key: ["authorization", "Bearer k"] },
    gemini: { url: "https://model.test/models/m:generateContent", answer: { candidates: [{ content: { parts: [{ text: "A" }] } }] }, key: ["x-goog-api-key", "k"] },
  };
  for (const [protocol, s] of Object.entries(shapes)) {
    const seen = [];
    const fetchImpl = async (url, init) => { seen.push({ url: String(url), init }); return { ok: true, status: 200, json: async () => s.answer, text: async () => JSON.stringify(s.answer) }; };
    const text = await callModel("hello", { env: { MODEL_NAME: "m", MODEL_ENDPOINT: "https://model.test/", MODEL_KEY: "k", MODEL_PROTOCOL: protocol }, fetchImpl });
    assert.equal(text, "A", protocol);
    assert.equal(seen[0].url, s.url, protocol);
    assert.equal(seen[0].init.headers[s.key[0]], s.key[1], protocol);
    assert.equal(String(seen[0].init.body).includes("\"k\""), false, "the key is never in the body");
  }
});

// ── the constraints ─────────────────────────────────────────────────────────

test("[C1] once the day's spending ceiling of 1 USD is reached, it writes no digest and says so", async () => {
  await inJob(async (job) => {
    const out = await runDigest({ text: "databases", context: {}, env: ENV, fetchImpl: hn(storiesOf(30, [4])).fetchImpl, call: async () => { throw new CeilingReached(); }, now: NOW, jobDir: job });
    assert.equal(out.code, 1);
    assert.equal(out.reply, CEILING_REACHED);
    assert.match(CEILING_REACHED, /ceiling of 1 USD/);
    assert.equal(out.digest, null);
    assert.equal(existsSync(join(job, "pieces.json")), false);
  });
  const env = { MODEL_NAME: "m", MODEL_ENDPOINT: "https://model.test", MODEL_KEY: "", MODEL_PROTOCOL: "openai-chat" };
  await assert.rejects(callModel("hello", { env, fetchImpl: async () => ({ ok: false, status: 402, json: async () => ({}), text: async () => "spending ceiling reached" }) }), CeilingReached);
  const decl = JSON.parse(readFileSync(join(here, "..", "agent-runtime-requirements.json"), "utf8"));
  const ceiling = decl.ceilings.find((c) => c.system === "text-reasoning");
  assert.equal(ceiling.per, "day");
  assert.equal(ceiling.suggested, 1);
});

test("[C2] it sends Hacker News no key, and the script holds no address of its own", async () => {
  const site = hn(storiesOf(30, [1]));
  const out = await runDigest({ text: "databases", context: {}, env: ENV, fetchImpl: site.fetchImpl, call: picker([1]).call, now: NOW });
  assert.equal(out.code, 0, out.reply);
  for (const c of site.calls) {
    const headers = Object.keys(c.init?.headers ?? {}).map((h) => h.toLowerCase());
    for (const h of ["authorization", "x-api-key", "cookie"]) assert.equal(headers.includes(h), false, `${c.url} carries ${h}`);
    assert.equal(/[?&](key|token|auth)=/i.test(c.url), false, c.url);
  }
  const source = readFileSync(join(here, "..", "scripts", "topic-digest.mjs"), "utf8");
  assert.equal(/https?:\/\/[a-z0-9-]+\.[a-z]/i.test(source), false, "no address is written in the script");
});

